def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Infer the repeating diagonal color pattern from the unmasked interior.
    best_p = 2
    for p in range(2, 11):
        groups = [Counter() for _ in range(p)]
        total = 0
        for r in range(3, h):
            for c in range(3, w):
                v = grid[r][c]
                if v:
                    groups[(r + c) % p][v] += 1
                    total += 1
        matches = sum(max(g.values(), default=0) for g in groups)
        if total and matches / total >= 0.90:
            best_p = p
            break

    groups = [Counter() for _ in range(best_p)]
    for r in range(3, h):
        for c in range(3, w):
            v = grid[r][c]
            if v:
                groups[(r + c) % best_p][v] += 1
    pattern = [g.most_common(1)[0][0] if g else 0 for g in groups]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = pattern[(r + c) % best_p]

    return out
